  const gx = sabEnd(a0, b0);
  const deep = third ? P2.third + P2.h : P2.low + P2.h;
  const runW = lang === "en" ? 330 : 410;
  const over = lowLab && lowLab.own && lowLab.p[0] > lowLab.p[1];
  const places = [];
