  const [fa, setFa] = useState(2);
  const [fb, setFb] = useState(7);
  const [fk, setFk] = useState(2);
  const [lower, setLower] = useState(null);
  const [lab, setLab] = useState(null);
  const [row, setRow] = useState([]);
  const clear = () => {
    tl.stop();
    setLower(null);
    setLab(null);
    setRow([]);
  };
